// Copies the IDL generated by `anchor build` into the frontend.
import { copyFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const out = resolve(root, "app/src/idl");
mkdirSync(out, { recursive: true });
copyFileSync(resolve(root, "target/idl/voting.json"), resolve(out, "voting.json"));
copyFileSync(resolve(root, "target/types/voting.ts"), resolve(out, "voting.ts"));
console.log("IDL synced to app/src/idl");
